35	func TestKVParseCommands(t *testing.T) {
36		cases := []struct {
37			command    string
38			wantOp     kvOperation
39			wantReason string
40		}{
41			{"set x=1", kvOperation{key: "x", value: "1"}, ""},
42			{"set x=", kvOperation{key: "x", value: ""}, ""},           // 空值
43			{"set k=a b c", kvOperation{key: "k", value: "a b c"}, ""}, // 值含空格
44			{"set k=a=b=c", kvOperation{key: "k", value: "a=b=c"}, ""}, // 值含额外等号
45			{"set k=你好 世界", kvOperation{key: "k", value: "你好 世界"}, ""}, // 中文值
46			{"set k=1 ", kvOperation{key: "k", value: "1 "}, ""},       // 尾部空白保留在值里
47			{"delete x", kvOperation{isDelete: true, key: "x"}, ""},
48			{"delete 键", kvOperation{isDelete: true, key: "键"}, ""},
49			{"set", kvOperation{}, ApplyReasonUnknownCommand}, // 没有空格与键
50			{"delete", kvOperation{}, ApplyReasonUnknownCommand},
51			{"set x", kvOperation{}, ApplyReasonSetMissingEquals},     // 缺等号
52			{"set =1", kvOperation{}, ApplyReasonEmptyKey},            // 空键
53			{"set  x=1", kvOperation{}, ApplyReasonKeyHasWhitespace},  // 两个空格：键以空格开头
54			{"set x y=1", kvOperation{}, ApplyReasonKeyHasWhitespace}, // 键含空白
55			{"set\tx=1", kvOperation{}, ApplyReasonUnknownCommand},    // 制表符不是普通空格
56			{"delete x y", kvOperation{}, ApplyReasonKeyHasWhitespace},
57			{"delete x ", kvOperation{}, ApplyReasonKeyHasWhitespace}, // 尾部空白不裁剪
58			{"delete a=b", kvOperation{}, ApplyReasonKeyHasEquals},    // 键含等号
59			{" set x=1", kvOperation{}, ApplyReasonUnknownCommand},    // 前导空白不裁剪
60			{"SET x=1", kvOperation{}, ApplyReasonUnknownCommand},     // 区分大小写
61			{"get x", kvOperation{}, ApplyReasonUnknownCommand},
62			{"", kvOperation{}, ApplyReasonUnknownCommand},
63		}
64		for _, tc := range cases {
65			op, reason := parseKVCommand(tc.command)
66			if reason != tc.wantReason {
67				t.Fatalf("parseKVCommand(%q) reason = %q, want %q", tc.command, reason, tc.wantReason)
68			}
69			if tc.wantReason == "" && op != tc.wantOp {
70				t.Fatalf("parseKVCommand(%q) = %+v, want %+v", tc.command, op, tc.wantOp)
71			}
72		}
73	}
