442		// 同一个结果对象先读启用应用的结果，再读未启用的：后一次输出不得残留
443		// 前一次的键值表、错误或应用位置。
444		enabled := runKV(t, InitialState{CurrentTerm: 1, CommittedIndex: 1, Log: []LogEntry{
445			entry(1, 1, "set x=1"),
446		}})
447		disabled := run(t, InitialState{CurrentTerm: 1, CommittedIndex: 1, Log: []LogEntry{
448			entry(1, 1, "set x=1"),
449		}})
450		enabledJSON, err := json.Marshal(enabled)
451		if err != nil {
452			t.Fatal(err)
453		}
454		disabledJSON, err := json.Marshal(disabled)
455		if err != nil {
456			t.Fatal(err)
457		}
458		var out ReplicateOutput
459		if err := json.Unmarshal(enabledJSON, &out); err != nil {
460			t.Fatal(err)
461		}
462		if err := json.Unmarshal(disabledJSON, &out); err != nil {
463			t.Fatal(err)
464		}
465		body, err := json.Marshal(out)
466		if err != nil {
467			t.Fatal(err)
468		}
469		for _, field := range []string{"appliedIndex", "applyError", "finalAppliedIndex", "finalKV", "finalApplyError"} {
470			if strings.Contains(string(body), field) {
471				t.Fatalf("stale apply field %q after reusing object: %s", field, body)
472			}
473		}
474		if out.FinalKV != nil || out.FinalAppliedIndex != nil || out.FinalApplyError != nil {
475			t.Fatalf("stale apply state in %+v", out)
476		}
477	}
