479	func TestKVAppendResultRoundTripStandalone(t *testing.T) {
480		out := runKV(t, InitialState{CurrentTerm: 1},
481			AppendRequest{Term: 1, PrevLogIndex: 0, PrevLogTerm: 0, LeaderCommit: 0})
482		encoded, err := json.Marshal(out.Results[0])
483		if err != nil {
484			t.Fatal(err)
485		}
