488			t.Fatal(err)
489		}
490		reencoded, err := json.Marshal(decoded)
491		if err != nil {
492			t.Fatal(err)
493		}
494		body := string(reencoded)
495		if !strings.Contains(body, `"appliedIndex":0`) || !strings.Contains(body, `"applyError":null`) {
496			t.Fatalf("standalone result round trip lost apply fields: %s", body)
