500	func TestKVRoundTripRejectsBadFieldTypes(t *testing.T) {
501		for _, data := range []string{
502			`{"results":[],"finalTerm":0,"finalCommittedIndex":0,"finalLog":[],"finalAppliedIndex":"0"}`,
503			`{"results":[],"finalTerm":0,"finalCommittedIndex":0,"finalLog":[],"finalKV":[]}`,
504			`{"results":[],"finalTerm":0,"finalCommittedIndex":0,"finalLog":[],"finalApplyError":{"index":"2","reason":"x"}}`,
505			`{"results":[{"accepted":true,"reason":"ok","term":1,"committedIndex":0,"appliedIndex":"0"}],"finalTerm":1,"finalCommittedIndex":0,"finalLog":[]}`,
506		} {
507			var out ReplicateOutput
508			if err := json.Unmarshal([]byte(data), &out); err == nil {
509				t.Fatalf("expected decode error for %s", data)
510			}
511		}
512	}
