514	// decodeMap 把 JSON 解码为通用对象，便于只按“键是否出现”断言输出形状
515	// （不能用字符串包含判断：appliedIndex 是 finalAppliedIndex 的子串）。
516	func decodeMap(t *testing.T, data []byte) map[string]any {
517		t.Helper()
518		var m map[string]any
519		if err := json.Unmarshal(data, &m); err != nil {
520			t.Fatalf("decode %s: %v", data, err)
