525	func mustHaveKeys(t *testing.T, m map[string]any, where string, keys ...string) {
526		t.Helper()
527		for _, key := range keys {
528			if _, ok := m[key]; !ok {
529				t.Fatalf("%s: expected key %q present in %v", where, key, m)
