559	// TestKVRoundTripPartialPerRequestFields 覆盖逐条请求一层只出现部分应用字段
560	// 的约定：appliedIndex 与 applyError 同组，出现任意一个再次输出就要带齐；
561	// 缺索引补 0、无错误补 null；字段出现与值为空是两回事（只有 null 错误也算
562	// 记录了应用状态）；已提供的非零索引与错误中的索引、原因原样保留。
563	func TestKVRoundTripPartialPerRequestFields(t *testing.T) {
564		cases := []struct {
565			name      string
566			extra     string
567			wantIndex float64
568			wantError any // nil 表示输出必须为 null；否则为期望的错误对象
569		}{
570			{"only zero applied index", `"appliedIndex":0`, 0, nil},
571			{"only nonzero applied index", `"appliedIndex":5`, 5, nil},
572			{"only null apply error", `"applyError":null`, 0, nil},
573			{"only apply error object",
574				`"applyError":{"index":3,"reason":"boom"}`, 0,
575				map[string]any{"index": float64(3), "reason": "boom"}},
576		}
577		for _, tc := range cases {
578			t.Run(tc.name, func(t *testing.T) {
579				data := `{"accepted":true,"reason":"ok","term":2,"committedIndex":1,` + tc.extra + `}`
580				var result AppendResult
581				if err := json.Unmarshal([]byte(data), &result); err != nil {
582					t.Fatal(err)
583				}
584				reencoded, err := json.Marshal(result)
585				if err != nil {
586					t.Fatal(err)
587				}
588				m := decodeMap(t, reencoded)
589				mustHaveKeys(t, m, "per-request result", "appliedIndex", "applyError")
590				if m["appliedIndex"] != tc.wantIndex {
591					t.Fatalf("appliedIndex = %v, want %v: %v", m["appliedIndex"], tc.wantIndex, m)
592				}
593				if tc.wantError == nil {
594					if m["applyError"] != nil {
595						t.Fatalf("applyError = %v, want null: %v", m["applyError"], m)
596					}
597				} else if !reflect.DeepEqual(m["applyError"], tc.wantError) {
598					t.Fatalf("applyError = %v, want %v", m["applyError"], tc.wantError)
599				}
600				// 复制答复的既有字段不被部分应用字段干扰。
601				if m["accepted"] != true || m["reason"] != "ok" ||
602					m["term"] != float64(2) || m["committedIndex"] != float64(1) {
603					t.Fatalf("replication fields changed: %v", m)
604				}
605			})
606		}
607	}
608	
609	// TestKVRoundTripPartialFinalFields 覆盖最终结果一层的部分字段约定：
610	// finalAppliedIndex、finalKV、finalApplyError 同组；缺索引补 0、缺键值表补
611	// 空对象 {}、无错误补 null；只带空键值表也要保留索引与错误字段；非零索引、
612	// 键值内容、错误索引与原因原样保留。
613	func TestKVRoundTripPartialFinalFields(t *testing.T) {
614		cases := []struct {
615			name      string
616			extra     string
617			wantIndex float64
618			wantKV    any // nil 表示必须输出空对象 {}
619			wantError any // nil 表示必须输出 null
620		}{
621			{"only zero final applied index", `"finalAppliedIndex":0`, 0, map[string]any{}, nil},
622			{"only nonzero final applied index", `"finalAppliedIndex":7`, 7, map[string]any{}, nil},
623			{"only empty final kv", `"finalKV":{}`, 0, map[string]any{}, nil},
624			{"only nonempty final kv",
625				`"finalKV":{"a":"1","b":"x=y"}`, 0,
626				map[string]any{"a": "1", "b": "x=y"}, nil},
627			{"only null final apply error", `"finalApplyError":null`, 0, map[string]any{}, nil},
628			{"only final apply error object",
629				`"finalApplyError":{"index":2,"reason":"` + ApplyReasonSetMissingEquals + `"}`, 0,
630				map[string]any{},
631				map[string]any{"index": float64(2), "reason": ApplyReasonSetMissingEquals}},
632		}
633		for _, tc := range cases {
634			t.Run(tc.name, func(t *testing.T) {
635				data := `{"results":[],"finalTerm":2,"finalCommittedIndex":1,` +
636					`"finalLog":[{"index":1,"term":1,"command":"set a=1"}],` + tc.extra + `}`
637				var out ReplicateOutput
638				if err := json.Unmarshal([]byte(data), &out); err != nil {
639					t.Fatal(err)
640				}
641				reencoded, err := json.Marshal(out)
642				if err != nil {
643					t.Fatal(err)
644				}
645				m := decodeMap(t, reencoded)
646				mustHaveKeys(t, m, "final output", "finalAppliedIndex", "finalKV", "finalApplyError")
647				if m["finalAppliedIndex"] != tc.wantIndex {
648					t.Fatalf("finalAppliedIndex = %v, want %v: %v", m["finalAppliedIndex"], tc.wantIndex, m)
649				}
650				if !reflect.DeepEqual(m["finalKV"], tc.wantKV) {
651					t.Fatalf("finalKV = %v, want %v", m["finalKV"], tc.wantKV)
652				}
653				if tc.wantError == nil {
654					if m["finalApplyError"] != nil {
655						t.Fatalf("finalApplyError = %v, want null: %v", m["finalApplyError"], m)
656					}
657				} else if !reflect.DeepEqual(m["finalApplyError"], tc.wantError) {
658					t.Fatalf("finalApplyError = %v, want %v", m["finalApplyError"], tc.wantError)
659				}
660				// 任期、提交位置与日志内容保持原样。
661				if m["finalTerm"] != float64(2) || m["finalCommittedIndex"] != float64(1) {
662					t.Fatalf("final replication fields changed: %v", m)
663				}
664				log := m["finalLog"].([]any)
665				if !reflect.DeepEqual(log[0], map[string]any{"index": float64(1), "term": float64(1), "command": "set a=1"}) {
666					t.Fatalf("finalLog changed: %v", log)
667				}
668			})
669		}
670	}
671	
672	// TestKVRoundTripApplyLevelsIndependent 两层应用字段各自按本层是否出现判断：
673	// 最终结果记录了应用状态，不能让没有应用字段的请求答复凭空多出应用信息；某条
674	// 请求带有应用字段，也不能让最终结果或其他请求多出字段。同一输出中混合两种
675	// 请求答复时，读取再输出必须保留各自区别。
676	func TestKVRoundTripApplyLevelsIndependent(t *testing.T) {
677		perRequestKeys := []string{"appliedIndex", "applyError"}
678		finalKeys := []string{"finalAppliedIndex", "finalKV", "finalApplyError"}
679		cases := []struct {
680			name string
681			data string
682		}{
683			{
684				"final level applied, requests mixed plain and applied",
685				`{"results":[` +
686					`{"accepted":true,"reason":"ok","term":3,"committedIndex":0},` +
687					`{"accepted":false,"reason":"stale term: leader term is lower than current term","term":3,"committedIndex":0,"appliedIndex":2,"applyError":{"index":3,"reason":"boom"}}` +
688					`],"finalTerm":3,"finalCommittedIndex":0,"finalLog":[],` +
689					`"finalAppliedIndex":2,"finalKV":{"k":"v"},"finalApplyError":{"index":3,"reason":"boom"}}`,
690			},
691			{
692				"final level absent, requests mixed applied and plain",
693				`{"results":[` +
694					`{"accepted":true,"reason":"ok","term":1,"committedIndex":0,"appliedIndex":0,"applyError":null},` +
695					`{"accepted":true,"reason":"ok","term":1,"committedIndex":0}` +
696					`],"finalTerm":1,"finalCommittedIndex":0,"finalLog":[]}`,
697			},
698		}
699		for _, tc := range cases {
700			t.Run(tc.name, func(t *testing.T) {
701				var out ReplicateOutput
702				if err := json.Unmarshal([]byte(tc.data), &out); err != nil {
703					t.Fatal(err)
704				}
705				reencoded, err := json.Marshal(out)
706				if err != nil {
707					t.Fatal(err)
708				}
709				m := decodeMap(t, reencoded)
710				results := resultMaps(t, m)
711				if len(results) != 2 {
712					t.Fatalf("expected 2 results, got %d", len(results))
713				}
714				if strings.Contains(tc.data, `"finalAppliedIndex":2`) {
715					// 第一种情形：最终层有应用字段；请求 0 无、请求 1 有。
716					mustLackKeys(t, results[0], "plain request", perRequestKeys...)
717					mustHaveKeys(t, results[1], "applied request", perRequestKeys...)
718					if results[1]["appliedIndex"] != float64(2) {
719						t.Fatalf("request appliedIndex changed: %v", results[1])
720					}
721					if !reflect.DeepEqual(results[1]["applyError"],
722						map[string]any{"index": float64(3), "reason": "boom"}) {
723						t.Fatalf("request applyError changed: %v", results[1])
724					}
725					mustHaveKeys(t, m, "final output", finalKeys...)
726					if !reflect.DeepEqual(m["finalKV"], map[string]any{"k": "v"}) {
727						t.Fatalf("finalKV changed: %v", m["finalKV"])
728					}
729				} else {
730					// 第二种情形：最终层无应用字段；请求 0 有、请求 1 无。
731					mustHaveKeys(t, results[0], "applied request", perRequestKeys...)
732					if results[0]["appliedIndex"] != float64(0) || results[0]["applyError"] != nil {
733						t.Fatalf("applied request values changed: %v", results[0])
734					}
735					mustLackKeys(t, results[1], "plain request", perRequestKeys...)
736					mustLackKeys(t, m, "final output", finalKeys...)
737				}
738			})
739		}
740	}
741	
742	// TestKVRoundTripLegacyResultWithoutApplyFields 完全没有应用字段的旧结果保持
743	// 原有输出形状；接受状态、拒绝原因、任期、提交位置与日志内容原样保留。
744	func TestKVRoundTripLegacyResultWithoutApplyFields(t *testing.T) {
745		data := []byte(`{"results":[{"accepted":false,` +
746			`"reason":"stale term: leader term is lower than current term",` +
747			`"term":5,"committedIndex":1}],` +
748			`"finalTerm":5,"finalCommittedIndex":1,` +
749			`"finalLog":[{"index":1,"term":5,"command":"a"}]}`)
750		var out ReplicateOutput
751		if err := json.Unmarshal(data, &out); err != nil {
752			t.Fatal(err)
753		}
754		reencoded, err := json.Marshal(out)
755		if err != nil {
756			t.Fatal(err)
757		}
758		want := decodeMap(t, data)
759		got := decodeMap(t, reencoded)
760		if !reflect.DeepEqual(got, want) {
761			t.Fatalf("legacy result changed shape:\nwant %v\n got %v", want, got)
762		}
763		results := resultMaps(t, got)
764		mustLackKeys(t, results[0], "legacy request", "appliedIndex", "applyError")
765		mustLackKeys(t, got, "legacy final output",
766			"finalAppliedIndex", "finalKV", "finalApplyError")
767	}
768	
769	// TestKVRoundTripFailedReuseKeepsPreviousResult 复用已有结果对象再次读入时，
770	// 类型非法的 JSON 必须明确报错，且原有结果完整保留——即使错误藏在某条请求
771	// 答复内，随后输出也不能混入这次读入的任何部分内容。
772	func TestKVRoundTripFailedReuseKeepsPreviousResult(t *testing.T) {
773		original := runKV(t, InitialState{CurrentTerm: 1, CommittedIndex: 1, Log: []LogEntry{
774			entry(1, 1, "set x=1"),
775		}},
776			AppendRequest{Term: 1, PrevLogIndex: 1, PrevLogTerm: 1, LeaderCommit: 3,
777				Entries: []LogEntry{entry(2, 1, "set bad"), entry(3, 1, "set k=v")}},
778		)
779		originalJSON, err := json.Marshal(original)
780		if err != nil {
781			t.Fatal(err)
782		}
783		badInputs := []string{
784			// 错误位于某条请求答复内：应用索引写成字符串。
785			`{"results":[{"accepted":true,"reason":"ok","term":9,"committedIndex":9,"appliedIndex":"3"}],"finalTerm":9,"finalCommittedIndex":9,"finalLog":[]}`,
786			// 最终层：应用索引写成字符串。
787			`{"results":[],"finalTerm":9,"finalCommittedIndex":9,"finalLog":[],"finalAppliedIndex":"9"}`,
788			// 最终层：键值表写成数组。
789			`{"results":[],"finalTerm":9,"finalCommittedIndex":9,"finalLog":[],"finalKV":["nope"]}`,
790		}
791		for _, bad := range badInputs {
792			var out ReplicateOutput
793			if err := json.Unmarshal(originalJSON, &out); err != nil {
794				t.Fatal(err)
795			}
796			if err := json.Unmarshal([]byte(bad), &out); err == nil {
797				t.Fatalf("expected decode error for %s", bad)
798			}
799			reencoded, err := json.Marshal(out)
800			if err != nil {
801				t.Fatal(err)
802			}
803			if string(reencoded) != string(originalJSON) {
804				t.Fatalf("previous result not preserved after failed decode of %s:\nwant %s\n got %s",
805					bad, originalJSON, reencoded)
806			}
807		}
808	}
